/**
 * Static schematic for the Spider-Tracker map (ARCHITECTURE §2.3).
 * stations.json is generated by scripts/build-stations.ts; layout.json is hand-placed.
 * Both are empty placeholders until those exist.
 */
import type { RouteId } from '../lines';
import stationsJson from './stations.json';
import layoutJson from './layout.json';
import geoJson from './geo.json';

export type SchematicStation = { id: string; name: string };

/**
 * Ordered parent stations for one route and direction (direction_id 0 or 1).
 * Branching routes (Red) list each canonical pattern one after another; previousStation()
 * uses the first occurrence, which gives the right neighbour on both branches.
 */
export type RouteStations = { '0': SchematicStation[]; '1': SchematicStation[] };

export type StationsFile = {
  version: 1;
  generatedAt: string | null;
  routes: Partial<Record<RouteId, RouteStations>>;
};

export type Point = { x: number; y: number };

export type LayoutFile = {
  version: 1;
  /** Canvas size: 1600×1000. */
  width: number;
  height: number;
  /** Parent station id → canvas point. */
  stations: Record<string, Point>;
  /** Route id → polylines of station ids (one per canonical pattern; Red has two branches). */
  paths: Partial<Record<RouteId, string[][]>>;
};

export const stations = stationsJson as StationsFile;
export const layout = layoutJson as LayoutFile;

/** Real-world geometry for the geographic map; generated by scripts/build-geo.ts. */
export type GeoFile = {
  version: 1;
  generatedAt: string | null;
  /** [minLon, minLat, maxLon, maxLat] */
  bbox: [number, number, number, number];
  stations: Record<string, { name: string; lat: number; lon: number }>;
  /** Route id → simplified track polylines of [lon, lat]. */
  shapes: Partial<Record<RouteId, [number, number][][]>>;
};

export const geo = geoJson as unknown as GeoFile;
